/**
 * @method
 * @name scwin.etnChangePage
 * @author Inswave
 * @date 2026. 09. 29
 * @param tab
 * @returns
 * @hidden N
*/
scwin.etnChangePage = async function (tab) {
    /* sdd-asis-lifecycle:begin fn_EtnChangePage — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    form = (document.etnListForm || { elements: [] });
    const lastSaveStatCdInt = parseInt($c.util.getComponent('dma_readDataVO').get('lastSaveStatCd'));
    if (lastSaveStatCdInt == 0 && tab > 1) {
        await $c.win.alert('발행증권에 관한 사항을 먼저 저장해주세요.');
        return;
    } else {
        if (lastSaveStatCdInt == 1 && tab > 2) {
            await $c.win.alert('발행증권2(손실제한)에 관한 사항을 먼저 저장해주세요.');
            return;
        } else {
            if (lastSaveStatCdInt == 2 && tab > 3) {
                await $c.win.alert('발행회사에 관한 사항을 먼저 저장해주세요.');
                return;
            } else {
                if (lastSaveStatCdInt == 3 && tab > 4) {
                    await $c.win.alert('보증인/제3자LP에 관한 사항을 먼저 저장해주세요.');
                    return;
                }
            }
        }
    }
    if (tab == 1) {
        $c.util.getComponent('dma_EtnChangePageReq').set('method', 'lossLimitViewIsuTab');
    } else {
        if (tab == 2) {
            $c.util.getComponent('dma_EtnChangePageReq').set('method', 'lossLimitViewIsuTab2');
        } else {
            if (tab == 3) {
                $c.util.getComponent('dma_EtnChangePageReq').set('method', 'lossLimitViewIsurTab');
            } else {
                if (tab == 4) {
                    $c.util.getComponent('dma_EtnChangePageReq').set('method', 'lossLimitViewSrtyLpTab');
                } else {
                    return;
                }
            }
        }
    }
    form.action = 'LossLimitEtnList.do';
    await scwin.tx_fn_EtnChangePage();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.register
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.register = async function () {
    /* sdd-asis-lifecycle:begin fn_Register — as-is 원문 본문(전환 이관 · 포팅 적용됨) */

    if( !$c.lc.fn_isProcess('I') )  return;

    if("" + dma_readDataVO.get("applStatusCd") + "" === '02') {
        await $c.win.alert('반송된 신청입니다. 발행증권에 관한 사항 탭부터 다시 저장해야 합니다.');
        return;
    }

    if( !fn_validate(5) ) return;

    form = (document.etnListForm || { elements: [] });
    $c.util.getComponent('dma_RegisterReq').set('method', 'lossLimitSaveAttachFileTab');
    form.action = 'LossLimitEtnList.do';
    await scwin.tx_fn_Register();

    /* sdd-asis-lifecycle:end */
};


